using UnityEngine;

namespace Controllers.Enemy
{
    /// <summary>
    /// 怪物数值与数量随时间变化的计算器
    ///
    /// 时间线（总 15 分钟 = 900 秒）：
    ///   0s ─────────────── 600s(10min) ─────────────── 900s(15min,Boss出现)
    ///   │   数量逐渐增加     │   数量达到峰值(2x)       │   Boss出现后数量骤降(限制)
    ///   │   血量逐渐增加     │   血量持续上升           │   血量回落至初始值
    ///
    /// 数量曲线：0.5x(前3min) → 1x~2x(3~10min) → 维持2x → 骤降至0.5x(Boss出现后限流)
    /// 血量曲线：1x → 4x（900s 前线性增长）→ Boss 出现后回落至 1x
    /// </summary>
    public static class EnemyScalingCalculator
    {
        // ── 时间常量 ──
        private const float BossSpawnTime = 900f;   // 15 分钟 Boss 出现
        private const float PeakCountTime = 600f;   // 10 分钟数量达到峰值
        private const float EarlyGameEndTime = 180f; // 3 分钟前期结束

        // ── 数量倍率 ──
        private const float EarlyGameCountMultiplier = 0.5f;  // 前 3 分钟数量减半
        private const float MidGameCountMultiplier = 1f;      // 3 分钟后恢复正常数量
        private const float PeakCountMultiplier = 2f;          // 峰值数量倍率（初始的 2 倍）
        private const float PostBossCountMultiplier = 0.5f;    // Boss 出现后数量倍率（限制防卡）

        // ── 血量倍率 ──
        private const float InitialHpMultiplier = 1f;   // 初始血量倍率
        private const float PeakHpMultiplier = 4f;      // 峰值血量倍率（初始的 4 倍）
        private const float PostBossHpMultiplier = 1f; // Boss 出现后血量回落至初始

        // ── 过渡时间 ──
        private const float BossTransitionDuration = 60f; // Boss 出现后 60 秒内平滑过渡到初始值

        /// <summary>
        /// 根据当前游戏时间计算数量倍率
        /// 0~3min: 0.5x（前期减半）
        /// 3~10min: 1x → 2x 线性增长
        /// 10~15min: 维持 2x
        /// 15min+: 从 2x 平滑降至 0.5x（60秒过渡）
        /// </summary>
        public static float GetCountMultiplier(float currentTime)
        {
            if (currentTime < EarlyGameEndTime)
            {
                // 前 3 分钟：数量减半
                return EarlyGameCountMultiplier;
            }

            if (currentTime < PeakCountTime)
            {
                // 3 → 10min: 1x → 2x 线性增长
                float progress = (currentTime - EarlyGameEndTime) / (PeakCountTime - EarlyGameEndTime);
                return Mathf.Lerp(MidGameCountMultiplier, PeakCountMultiplier, progress);
            }

            if (currentTime < BossSpawnTime)
            {
                // 10 → 15min: 维持峰值
                return PeakCountMultiplier;
            }

            // Boss 出现后：从 2x → 0.5x 平滑过渡（60秒）
            if (currentTime < BossSpawnTime + BossTransitionDuration)
            {
                float progress = (currentTime - BossSpawnTime) / BossTransitionDuration;
                return Mathf.Lerp(PeakCountMultiplier, PostBossCountMultiplier, progress);
            }

            return PostBossCountMultiplier;
        }

        /// <summary>
        /// 根据当前游戏时间计算血量倍率
        /// 0~15min: 1x → 4x 线性增长
        /// 15min+: 从 4x → 1x 平滑过渡（60秒）
        /// </summary>
        public static float GetHpMultiplier(float currentTime)
        {
            if (currentTime < BossSpawnTime)
            {
                // 0 → 15min: 1x → 4x 线性增长
                float progress = currentTime / BossSpawnTime;
                return Mathf.Lerp(InitialHpMultiplier, PeakHpMultiplier, progress);
            }

            // Boss 出现后：从 4x → 1x 平滑过渡（60秒）
            if (currentTime < BossSpawnTime + BossTransitionDuration)
            {
                float progress = (currentTime - BossSpawnTime) / BossTransitionDuration;
                return Mathf.Lerp(PeakHpMultiplier, PostBossHpMultiplier, progress);
            }

            return PostBossHpMultiplier;
        }

        /// <summary>
        /// 根据当前游戏时间计算生成间隔倍率
        /// 数量倍率越高 → 生成间隔越短（更快生成）
        /// interval = baseInterval / countMultiplier
        /// </summary>
        public static float GetSpawnIntervalMultiplier(float currentTime)
        {
            return 1f / GetCountMultiplier(currentTime);
        }

        /// <summary>Boss 是否已出现</summary>
        public static bool IsBossPhase(float currentTime) => currentTime >= BossSpawnTime;

        // ── Dragon 生成概率 ──
        private const float DragonPeakTime = 480f;       // 8 分钟达到峰值
        private const float DragonInitialProbability = 0.05f;  // 初始 5%
        private const float DragonPeakProbability = 0.30f;     // 峰值 30%

        /// <summary>
        /// 根据当前游戏时间计算 Dragon 生成概率
        /// 0s: 5%（初始）
        /// 0~480s(8min): 5% → 30% 线性增长
        /// 480s+: 维持 30%
        /// </summary>
        public static float GetDragonSpawnProbability(float currentTime)
        {
            if (currentTime >= DragonPeakTime)
                return DragonPeakProbability;

            float progress = currentTime / DragonPeakTime;
            return Mathf.Lerp(DragonInitialProbability, DragonPeakProbability, progress);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

//枚举，记录当前元素

public enum Element
{
    Common,
    Lightning,
    Winter,
    Grass,
    Fire,
}

namespace Controllers.Character
{
    public class AttributePlayerBase
    {
        protected PlayerAttributeConfigSO config;

        protected bool isDead = false;
        protected float attackPower;
        protected float defensePower;
        protected float criticalMultiplier;
        protected float criticalChance;
        protected float maxHealth;
        protected float currentHealth;
        protected float moveSpeed;
        protected float attackInterval;
        protected float healthRecover;
        protected float attackspeed;
        protected int maxAttackCount;
        protected int comboCount;
        protected int empowerCharge;
        protected int multiTargetCount;
        protected Element currentElement = Element.Common;

        protected bool isSplit = false;
        protected int splitCount = 0;

        public AttributePlayerBase(PlayerAttributeConfigSO config)
        {
            this.config = config;

            maxHealth = config.baseMaxHealth;
            currentHealth = config.baseMaxHealth;
            moveSpeed = config.baseMoveSpeed;
            attackPower = config.baseAttackPower;
            defensePower = config.baseDefensePower;
            criticalMultiplier = config.baseCriticalMultiplier;
            criticalChance = config.baseCriticalChance;
            attackInterval = config.maxAttackInterval;
            healthRecover = config.baseHealthRecover;
            attackspeed = config.baseAttackSpeed;
            maxAttackCount = config.baseMaxAttackCount;
            comboCount = config.baseComboCount;
            empowerCharge = config.baseEmpowerCharge;
            multiTargetCount = config.baseMultiTargetCount;
            currentElement = Element.Common;
            isSplit = false;
            splitCount = 0;
        }

        public void SetAttackInterval(int attackInterval)
        {
            this.attackInterval = attackInterval;
        }

        //减少攻击间隔
        public void ReduceAttackInterval(int ratio)
        {
            //计算新的攻击速度
            attackspeed += ratio;
            float newRatio = ratio / 100f;
            //按百分比减少攻击间隔
            attackInterval -= (attackInterval * newRatio);
            //向下取整,保留2位小数
            attackInterval = Mathf.Round(attackInterval * 100) / 100;
            //如果攻击间隔小于最小值,则设置为最小值
            if (attackInterval < config.minAttackInterval)
            {
                attackInterval = config.minAttackInterval;
            }
        }

        //获取攻击间隔
        public float GetAttackInterval()
        {
            return attackInterval;
        }

        public float GetAttackSpeed()
        {
            return attackspeed;
        }

        public float GetHealthRecover()
        {
            return healthRecover;
        }

        public void SetIsDead(bool isDead)
        {
            this.isDead = isDead;
        }

        public bool GetIsDead()
        {
            return isDead;
        }

        public void SetMaxHealth(float maxHealth)
        {
            this.maxHealth = maxHealth;
        }

        public void AddCurrentHealth(float currentHealth)
        {
            this.currentHealth += currentHealth;
            //如果当前生命值大于最大生命值,则设置为最大生命值
            if (this.currentHealth > maxHealth)
            {
                this.currentHealth = maxHealth;
            }
        }

        public void SetMoveSpeed(float moveSpeed)
        {
            this.moveSpeed = moveSpeed;
        }

        public void AddMoveSpeed(float moveSpeed)
        {
            this.moveSpeed += moveSpeed;
        }

        public void SetCriticalMultiplier(float criticalMultiplier)
        {
            this.criticalMultiplier = criticalMultiplier;
        }

        public void AddCriticalMultiplier(float ratio)
        {
            float newRatio = ratio / 100f;
            criticalMultiplier += newRatio;
            //向下取整,保留2位小数
            criticalMultiplier = Mathf.Round(criticalMultiplier * 100) / 100;
        }

        public void SetCriticalChance(float criticalChance)
        {
            this.criticalChance = criticalChance;
        }

        public void AddCriticalChance(float ratio)
        {
            float newRatio = ratio / 100f;
            //按百分比增加暴击概率
            criticalChance += newRatio;
            //向下取整,保留2位小数
            criticalChance = Mathf.Round(criticalChance * 100) / 100;
            //如果暴击概率大于上限,则设置为上限
            if (criticalChance > config.maxCriticalChance)
            {
                criticalChance = config.maxCriticalChance;
            }
        }

        public void SetAttackPower(float attackPower)
        {
            this.attackPower = attackPower;
        }

        public void AddAttackPower(float ratio)
        {
            float newRatio = ratio / 100f;
            //按百分比增加攻击伤害
            attackPower += (attackPower * newRatio);
            //向下取整,没有小数位
            attackPower = Mathf.Round(attackPower * 1) / 1;
        }

        public void SetDefensePower(float defensePower)
        {
            this.defensePower = defensePower;
        }

        public void AddDefensePower(float ratio)
        {
            float newRatio = ratio / 100f;
            //按百分比增加防御伤害
            defensePower += (defensePower * newRatio);
            //向下取整,没有小数位
            defensePower = Mathf.Round(defensePower * 1) / 1;
        }

        public float GetCurrentHealth()
        {
            return currentHealth;
        }

        public float GetMaxHealth()
        {
            return maxHealth;
        }

        public void AddMaxHealth(float maxHealth)
        {
            this.maxHealth += maxHealth;
        }

        public float GetMoveSpeed()
        {
            return moveSpeed;
        }

        public float GetAttackPower()
        {
            return attackPower;
        }

        public float GetDefensePower()
        {
            return defensePower;
        }

        public float GetCriticalMultiplier()
        {
            return criticalMultiplier;
        }

        public float GetCriticalChance()
        {
            return criticalChance;
        }

        public void SetHealthRecover(float healthRecover)
        {
            this.healthRecover = healthRecover;
        }

        public void Damage(float damage)
        {
            if (isDead) return;

            currentHealth -= damage;
            if (currentHealth <= 0)
            {
                currentHealth = 0;
                isDead = true;
            }
        }

        public int GetMaxAttackCount()
        {
            return maxAttackCount;
        }

        public void AddMaxAttackCount(int attackCount)
        {
            this.maxAttackCount += attackCount;
            Debug.Log($"最大攻击次数增加{attackCount}次,当前最大攻击次数为{maxAttackCount}");
        }

        public int GetComboCount()
        {
            return comboCount;
        }

        public void AddComboCount(int comboCount)
        {
            this.comboCount += comboCount;
            Debug.Log($"连击次数增加{comboCount}次,当前连击次数为{comboCount}");
        }

        public int GetEmpowerCharge()
        {
            return empowerCharge;
        }

        public Element GetCurrentElement()
        {
            return currentElement;
        }

        public void SetCurrentElement(Element element)
        {
            currentElement = element;
        }

        public bool GetSplit()
        {
            return isSplit;
        }

        public void SetSplit(bool isSplit)
        {
            this.isSplit = isSplit;
        }

        public int GetSplitCount()
        {
            return splitCount;
        }

        public void SetSplitCount(int splitCount)
        {
            this.splitCount = splitCount;
        }

        public void AddSplitCount(int count)
        {
            this.splitCount += count;
        }

        public int GetMultiTargetCount()
        {
            return multiTargetCount;
        }

        public void AddMultiTargetCount(int count)
        {
            this.multiTargetCount += count;
            Debug.Log($"多目标锁定数量增加{count}个,当前可锁定{multiTargetCount}个目标");
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using Managers; // TODO: GamePauseManager.isPaused 移到事件通道后移除
using Core;
using Core.Channels.Game;
using Controllers.Player;
using UnityEngine;
using UnityEngine.AI;

namespace Controllers.Enemy
{
    /// <summary>
    /// 可攻击玩家的敌人类，继承自 EnemyBase。
    /// 通过距离判定替代碰撞体触发，提高大批量怪物时的性能。
    /// 无攻击动画，怪物紧贴玩家时自动按间隔造成伤害。
    ///
    /// LOD (Level of Detail) 分级优化：
    /// 根据与最近玩家的距离动态调整行为精度，远处敌人降低更新频率以提升性能。
    /// 在大批量怪物场景中，远处怪物消耗显著降低。
    /// </summary>
    public class AttackableEnemy : EnemyBase
    {
        [Header("攻击设置")]
        [SerializeField]
        protected float attackDamage = 10f;

        [SerializeField, Tooltip("攻击距离（怪物与玩家的距离小于此值时造成伤害）")]
        protected float attackRange = 2f;

        [SerializeField]
        protected float pathUpdateInterval = 0.3f; // NavMesh寻路更新间隔（秒）

        [Header("LOD 分级优化")]
        [SerializeField, Tooltip("LOD 0 近距离阈值（米），小于此值执行完整行为")]
        private float lod0Distance = 10f;

        [SerializeField, Tooltip("LOD 1 中距离阈值（米），在此值与 lod0 之间执行降级行为")]
        private float lod1Distance = 30f;

        [SerializeField, Tooltip("LOD 等级更新间隔（秒），每隔多久重新计算一次 LOD")]
        private float lodRefreshInterval = 0.5f;

        [SerializeField, Tooltip("LOD 1 攻击检测间隔倍率（越大攻击检测越慢）")]
        private float lod1AttackIntervalMultiplier = 3f;

        [SerializeField, Tooltip("LOD 2 是否冻结动画（animator.speed = 0，恢复时自动还原）")]
        private bool lod2FreezeAnimation = true;

        [SerializeField, Tooltip("LOD 2 是否完全禁用攻击检测")]
        private bool lod2DisableAttack = true;

        private NavMeshAgent navMeshAgent;
        private float pathUpdateTimer;

        protected float attackInterval = 0.7f;
        protected float attackCooldownTimer = 0f;

        // LOD 运行时状态
        private LODLevel currentLOD = LODLevel.Full;
        private LODLevel previousLOD = LODLevel.Full;
        private float lodRefreshTimer;
        private float sqrLod0;
        private float sqrLod1;
        private float sqrAttackRange;

        /// <summary>
        /// LOD 等级枚举
        /// </summary>
        protected enum LODLevel
        {
            Full,    // 近距离（< lod0Distance）：完整行为
            Reduced, // 中距离（lod0Distance ~ lod1Distance）：降级行为
            Minimal  // 远距离（> lod1Distance）：最小行为
        }

        protected override void Start()
        {
            base.Start();
            navMeshAgent = GetComponent<NavMeshAgent>();
            if (navMeshAgent != null)
            {
                navMeshAgent.speed = enemyData.attribute.moveSpeed;
            }

            // 预计算平方距离阈值，避免每帧重复计算
            sqrLod0 = lod0Distance * lod0Distance;
            sqrLod1 = lod1Distance * lod1Distance;
            sqrAttackRange = attackRange * attackRange;
        }

        protected override void Update()
        {
            base.Update();
            if (GamePauseManager.isPaused || enemyData.currentState == EnemyState.Die)
            {
                if (navMeshAgent != null && navMeshAgent.isActiveAndEnabled && navMeshAgent.isOnNavMesh)
                    navMeshAgent.isStopped = true;
                return;
            }
            else
            {
                if (navMeshAgent != null && navMeshAgent.isActiveAndEnabled && navMeshAgent.isOnNavMesh)
                    navMeshAgent.isStopped = false;
            }

            // 定期刷新 LOD 等级（避免每帧遍历所有玩家）
            lodRefreshTimer -= UnityEngine.Time.deltaTime;
            if (lodRefreshTimer <= 0f)
            {
                UpdateLODLevel();
                lodRefreshTimer = lodRefreshInterval;
            }

            // LOD 2（远距离）且启用了远距离禁用攻击时，跳过攻击检测
            if (currentLOD == LODLevel.Minimal && lod2DisableAttack)
                return;

            DealDamageToPlayers();
        }

        /// <summary>
        /// 根据与最近玩家的距离更新 LOD 等级。
        /// 当 LOD 发生切换时自动触发动画/寻路等组件调整。
        /// </summary>
        private void UpdateLODLevel()
        {
            float sqrDist = GetSqrDistanceToNearestPlayer();

            LODLevel newLevel;
            if (sqrDist <= sqrLod0)
            {
                newLevel = LODLevel.Full;
            }
            else if (sqrDist <= sqrLod1)
            {
                newLevel = LODLevel.Reduced;
            }
            else
            {
                newLevel = LODLevel.Minimal;
            }

            if (newLevel != currentLOD)
            {
                previousLOD = currentLOD;
                currentLOD = newLevel;
                OnLODLevelChanged(previousLOD, currentLOD);
            }
        }

        /// <summary>
        /// LOD 等级切换时的回调，处理动画冻结 / NavMesh 禁用等副作用。
        /// </summary>
        private void OnLODLevelChanged(LODLevel from, LODLevel to)
        {
            bool wasMinimal = from == LODLevel.Minimal;
            bool isMinimal = to == LODLevel.Minimal;

            if (isMinimal && !wasMinimal)
            {
                // 进入 LOD 2（远距离）：冻结动画 + 禁用 NavMesh
                if (lod2FreezeAnimation && animator != null)
                    animator.speed = 0f;

                if (navMeshAgent != null && navMeshAgent.enabled)
                    navMeshAgent.enabled = false;
            }
            else if (!isMinimal && wasMinimal)
            {
                // 离开 LOD 2：恢复动画 + 重新启用 NavMesh
                if (animator != null)
                    animator.speed = 1f;

                if (navMeshAgent != null && !navMeshAgent.enabled)
                {
                    navMeshAgent.enabled = true;
                    navMeshAgent.updatePosition = true;

                    // 查找最近的有效 NavMesh 位置（线性移动可能走离 NavMesh）
                    if (NavMesh.SamplePosition(transform.position, out var hit, 10f, NavMesh.AllAreas))
                    {
                        transform.position = hit.position;
                        navMeshAgent.Warp(hit.position);
                    }

                    navMeshAgent.speed = enemyData.attribute.moveSpeed;
                }
            }
        }

        /// <summary>
        /// 获取距离最近玩家的平方距离（使用 sqrMagnitude 避免开根号）
        /// </summary>
        private float GetSqrDistanceToNearestPlayer()
        {
            var players = PlayerManager.instance != null
                ? PlayerManager.instance.ActivePlayerObjects
                : null;

            if (players == null || players.Count == 0)
                return float.MaxValue;

            Vector3 enemyPos = transform.position;
            float minSqrDist = float.MaxValue;

            for (int i = 0; i < players.Count; i++)
            {
                var player = players[i];
                if (player == null) continue;

                Vector3 diff = player.transform.position - enemyPos;
                float sqrDist = diff.sqrMagnitude;
                if (sqrDist < minSqrDist)
                {
                    minSqrDist = sqrDist;
                }
            }

            return minSqrDist;
        }

        /// <summary>
        /// 距离判定：对攻击范围内的所有玩家造成伤害。
        /// 使用 sqrMagnitude 避免开根号，提高性能。
        ///
        /// LOD 优化：
        /// - LOD 0：正常攻击间隔
        /// - LOD 1：攻击间隔乘以倍率，降低检测频率
        /// - LOD 2：在调用前已被跳过（由 lod2DisableAttack 控制）
        /// </summary>
        private void DealDamageToPlayers()
        {
            if (enemyData.currentState == EnemyState.Die)
                return;

            // LOD 1（中距离）：放大攻击间隔，减少不必要的伤害检测
            float effectiveInterval = attackInterval;
            if (currentLOD == LODLevel.Reduced)
            {
                effectiveInterval = attackInterval * lod1AttackIntervalMultiplier;
            }

            attackCooldownTimer += UnityEngine.Time.deltaTime;
            if (attackCooldownTimer < effectiveInterval)
                return;

            attackCooldownTimer = 0f;

            // 从 PlayerManager 获取所有活跃玩家
            var players = PlayerManager.instance != null
                ? PlayerManager.instance.ActivePlayerObjects
                : null;

            if (players == null || players.Count == 0)
                return;

            Vector3 enemyPos = transform.position;

            for (int i = 0; i < players.Count; i++)
            {
                var player = players[i];
                if (player == null) continue;

                // 距离平方比较，避免开根号
                Vector3 diff = player.transform.position - enemyPos;
                if (diff.sqrMagnitude <= sqrAttackRange)
                {
                    DamageEventArgs damageEventArgs = DamageEventArgs.GetShared(
                        Element.Common,
                        gameObject,
                        player,
                        enemyData.attribute.attackPower,
                        false,
                        0f
                    );
                    EventChannelLocator.MainContainer.playerDamageEventChannel.Raise(damageEventArgs);
                }
            }
        }

        protected override void OnEnable()
        {
            base.OnEnable();
            if (PlayerTarget == null)
                return;
            if (navMeshAgent != null)
            {
                navMeshAgent.speed = enemyData.attribute.moveSpeed;
                navMeshAgent.updatePosition = true;
            }

            // 获取当前游戏时间
// 获取当前游戏时间
            var timeQuery = new TimeQueryData();
            EventChannelLocator.MainContainer.timeQueryChannel?.Query(timeQuery);
            float currentTime = timeQuery.currentTime;

            // 基础血量（与 EnemyBase.Awake 中一致）
            const float baseMaxHealth = 500f;

            // 根据游戏时间计算血量倍率（1x → 4x，Boss 出现后回落至 1x）
            float hpMultiplier = EnemyScalingCalculator.GetHpMultiplier(currentTime);
            float newMaxHealth = baseMaxHealth * hpMultiplier;
            enemyData.attribute.maxHealth = newMaxHealth;
            enemyData.attribute.currentHealth = newMaxHealth;

            // 重置 LOD 计时器，从池中取出时立即评估 LOD
            lodRefreshTimer = 0f;
        }

        protected override void OnDisable()
        {
            base.OnDisable();
            // 恢复动画速度，防止对象池中间残留冻结状态
            if (animator != null)
                animator.speed = 1f;
            // 恢复 NavMeshAgent，防止池中残留禁用状态
            if (navMeshAgent != null && !navMeshAgent.enabled)
                navMeshAgent.enabled = true;
            TransitionToState(EnemyState.Idle);
        }

        protected override void UpdateRun()
        {
            // 重新评估目标，确保已被移除的死亡玩家不再被追踪
            TrackPlayer();

            if (PlayerTarget == null)
            {
                TransitionToState(EnemyState.Idle);
                return;
            }

            if (GamePauseManager.isPaused)
                return;

            // LOD 2（远距离）：线性移动，完全绕过 NavMesh 降低成本
            if (currentLOD == LODLevel.Minimal)
            {
                Vector3 direction = (PlayerTarget.transform.position - transform.position).normalized;
                transform.position += direction * enemyData.attribute.moveSpeed * UnityEngine.Time.deltaTime;
                // 仅旋转 Y 轴朝向玩家
                transform.LookAt(new Vector3(
                    PlayerTarget.transform.position.x,
                    transform.position.y,
                    PlayerTarget.transform.position.z));
                return;
            }

            // LOD 0 / 1：正常 NavMesh 寻路
            if (navMeshAgent == null || !navMeshAgent.isActiveAndEnabled || !navMeshAgent.isOnNavMesh)
                return;

            navMeshAgent.isStopped = false;

            // 间隔更新寻路目标
            pathUpdateTimer -= UnityEngine.Time.deltaTime;
            if (pathUpdateTimer <= 0f)
            {
                navMeshAgent.SetDestination(PlayerTarget.transform.position);
                pathUpdateTimer = pathUpdateInterval;
            }
        }

        protected override void EnterRun()
        {
            base.EnterRun();
            pathUpdateTimer = 0f;
        }

        protected override void EnterDie()
        {
            base.EnterDie();
        }

        protected override void UpdateDie()
        {
            base.UpdateDie();
        }

        protected override void ExitDie()
        {
            base.ExitDie();
        }

        public override void TakeDamage(DamageEventArgs damageEventArgs)
        {
            base.TakeDamage(damageEventArgs);
        }

        protected override void DropExperience()
        {
            base.DropExperience();
        }

        public override void ResetState()
        {
            base.ResetState();
            // 恢复 LOD 2 可能影响到的组件状态
            if (animator != null)
                animator.speed = 1f;
            if (navMeshAgent != null && !navMeshAgent.enabled)
                navMeshAgent.enabled = true;

            // 重置 LOD 运行时状态
            currentLOD = LODLevel.Full;
            previousLOD = LODLevel.Full;
            lodRefreshTimer = 0f;
            pathUpdateTimer = 0f;
            attackCooldownTimer = 0f;
        }
    }
}

